    document.getElementById("slApp").innerHTML=`<div class="sl-app"><aside class="sl-sidebar" id="slSidebar"><div class="sl-brand"><span class="sl-brand-mark">${isTaxi?"🚕":"🚘"}</span><div class="sl-brand-copy"><strong>VAREX</strong><small>${brand}<br>MANAGEMENT SYSTEM</small><div class="sl-online"><i></i><span>${t("النظام متصل وجاهز للعمل","System online and ready")}</span></div></div></div><nav class="sl-nav">${navGroups.map(([group,items])=>{const visible=items.filter(item=>enabled.has(item[2]));return visible.length?`<div class="sl-nav-group">${t(group[0],group[1])}</div>${visible.map(item=>`<a class="${page===item[0]?"active":""}" href="./${item[1]}">${svg(item[0])}<span>${t(item[3],item[4])}</span></a>`).join("")}`:""}).join("")}<div class="sl-nav-actions"><button type="button" id="slSwitchUser">${svg("switchUser")}<span>${t("تبديل المستخدم","Switch User")}</span></button><button class="danger" type="button" id="slLogout">${svg("power")}<span>${t("تسجيل الخروج","Sign Out")}</span></button></div><a href="../systems.html?manage=1">${svg("apps")}<span>${t("كل أنظمة VAREX","All VAREX Systems")}</span></a></nav><div class="sl-sidebar-foot">VAREX ${brand} · 1.1.0</div></aside><div class="sl-overlay" id="slOverlay"></div><section class="sl-main"><header class="sl-topbar"><div class="sl-page-title"><button class="sl-icon-btn sl-menu-btn" id="slMenuBtn" type="button">${svg("menuButton")}</button><span class="sl-page-icon">${svg(page)}</span><div><h2>${t(meta[3],meta[4])}</h2><small>VAREX · ${brand}</small></div></div><div class="sl-top-actions"><div class="sl-chip">${svg("clock")}<strong id="slClock">--:--</strong></div><div class="sl-chip date-chip">${svg("calendar")}<strong id="slDate">--/--/----</strong></div><a class="sl-top-link" href="../systems.html?manage=1">${svg("apps")}<span>${t("الأنظمة","Systems")}</span></a><div class="sl-language-wrap"><button class="sl-language" id="slLanguage" type="button" aria-expanded="false">${svg("globe")}<span>${language==="ar"?"العربية":"English"}</span>${svg("chevron")}</button><div class="sl-language-menu" id="slLanguageMenu"><button type="button" data-language="ar" class="${language==="ar"?"active":""}">العربية</button><button type="button" data-language="en" class="${language==="en"?"active":""}">English</button></div></div><button class="sl-icon-btn ${hapticEnabled?"active":""}" id="slHaptic" type="button">${svg("vibration")}</button><button class="sl-icon-btn ${soundEnabled?"active":""}" id="slSound" type="button">${svg("sound")}</button><button class="sl-icon-btn" type="button">${svg("bell")}<i class="sl-alert-dot"></i></button></div></header><main class="sl-content" id="slContent"></main></section></div><div class="sl-modal-backdrop" id="slModal"></div><div class="sl-modal-backdrop" id="slConfirm"></div><div class="sl-toast" id="slToast"><i>✓</i><span></span></div>`;
    bindShell();renderPage();
